"use client";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
import { SIDEBAR_CONTENT } from "@/components/features/Orders/Sidebars/US Rules/us-auth-sidebar.content";
import { Margin } from "@mui/icons-material";

(pdfMake as any).vfs = (pdfFonts as any).vfs;

export interface PrintCoverPayload {
  fileName: string;
  orderId: number;
  shipAddress?: string;
  billAddress?: string;
  emailAddress?: string;
  payLaterOptions?: string;
  labelByMail?: boolean;
  pickupOrDropOff?: boolean;
  useUserCourier?: boolean;
  regionId?: number;
  regionNote?: string;
  regContactName?: string;
  regAddress?: string;
  regCity?: string;
  regCountry?: string;
  regPostalCode?: string;
  regPhoneNumber?: string;
  userDetails: {
    customerId?: string;
    customerName?: string;
    userName?: string;
    email?: string;
    contactNo?: string;
  };
  returnAddress?: {
    name?: string;
    address?: string;
    city?: string;
    postalCode?: string;
    phone?: string;
    country?: string;
  };
  region?: {
    address?: string;
    city?: string;
    company?: string;
    contactName?: string;
    country?: string;
    phoneNumber?: string;
    postalCode?: string;
    state?: string;
  };
  shppingInstructions?: {
    labelByMail?: boolean;
    pickupOrDropOff?: boolean;
    useUserCourier?: boolean;
    regionId?: number;
    payLaterOptions?: string;

  };
  documents: Array<{
    docId: number;
    orderId?: number;
    barcode?: string;
    countryName?: string;
    originCountryName?: string;
    isRush?: boolean;
    isScan?: boolean;
    isPostScan?: boolean;
    docCategoryId?: number;
    docCategoryName?: string;
    createdAt?: string | Date;
    instructions?: string;
    isGeneralSoftCopy?: string;
    instructionsList?: string[];
    invoiceReference?: string;
    internalReference?: string;
    orderAmount?: number;
    paidAmount?: number;
    estDateOfCompletion?: string;
    stops?: Array<{
      stopName: string;
      description?: string;
      processDays?: number;
    }>;
  }>;
}

export type PdfAction = "download" | "open" | "print";

const logoBase64 = "data:image/jpeg;base64,";

export const generatePDF = async (data: PrintCoverPayload, action: PdfAction = "download") => {
  const content: any[] = [];
  const getEmbassySidebarContent = (countryName?: string) => {
    const normalized = (countryName ?? "").trim().toLowerCase();
    switch (normalized) {
      case "iraq":
        return SIDEBAR_CONTENT.IRAQ_DOC;
      case "lebanon":
        return SIDEBAR_CONTENT.LEBANON_DOC;
      case "taiwan":
        return SIDEBAR_CONTENT.TAIWAN_DOC;
      default:
        return null;
    }
  };

  // ---------- For each document ----------
  data.documents.forEach((doc, index) => {
    // Main table with header and all sections
    content.push({
      table: {
        headerRows: 1,
        widths: ["100%"],
        body: [
          // Header row with logo, company info, and barcode
          [
            {
              columns: [
                {
                  width: "auto",
                  stack: [
                    {
                      columns: [
                        {
                          image: "logo",
                          fit: [110, 110],
                          width: 110,
                          margin: [2, 13, 10, 0],
                        },
                        {
                          text: [
                            "",
                            { text: "\n" },
                            {
                              text: "Washington Consular Services",
                              fontSize: 15,
                              color: "#C70039",
                              bold: true,
                              decoration: "underline",
                            },
                            { text: "\n" },
                            { text: "Mailing Address:", italics: true },
                            {
                              text: "  20 Courthouse Square,\nSuite 219, Rockville, MD 20850",
                              bold: true,
                            },
                            { text: "\n" },
                            { text: "Tel:", italics: true },
                            { text: "  301-605-1500  | ", bold: true },
                            { text: " Fax:", italics: true },
                            { text: "  301-605-1510", bold: true },
                            { text: "\n" },
                            { text: "Email:", italics: true },
                            { text: "  wcs@wcss.com  | ", bold: true },
                            { text: " Web:", italics: true },
                            { text: "  wcss.com", bold: true },
                          ],
                          alignment: "left",
                          fontSize: 10,
                          margin: [20, 4, 0, 5],
                        },
                      ],
                    },
                  ],
                },
                {
                  width: "*",
                  text: "",
                },
                {
                  image: doc.barcode ? `data:image/jpeg;base64,${doc.barcode}` : logoBase64,
                  width: 150,
                  alignment: "right",
                  margin: [0, 35, 0, 0],
                },
              ],
            },
          ],
          // Document ID header row
          [
            {
              columns: [
                {
                  width: "33.33%",
                  alignment: "left",
                  text: `DOC ID: ${doc.docId}`,
                },
                {
                  width: "33.33%",
                  text: `ORDER NO: W${doc.orderId ?? data.orderId}`,
                },
                {
                  width: "33.33%",
                  text: (doc.countryName ?? "").toUpperCase(),
                },
              ],
              fillColor: "#cccccc",
              fontSize: 13,
              margin: [5, 5, 5, 5],
              alignment: "left",
              bold: true,
            },
          ],
          // Main content row with three columns
          [
            {
              columns: [
                // Left column - Document details
                {
                  width: "33.33%",
                  text: [
                    "",
                    { text: "\n" },
                    {
                      text: "Doc Type: ",
                      background: doc.docCategoryId === 525 ? "#86f7aa" : "#FFFFFF",
                    },
                    {
                      text: doc.docCategoryName ?? "-",
                      bold: true,
                      background: doc.docCategoryId === 525 ? "#86f7aa" : "#FFFFFF",
                    },
                    {
                      text: "\n Origin Country: ",
                      background: doc.docCategoryId === 525 ? "#86f7aa" : "#FFFFFF",
                    },
                    {
                      text: doc.originCountryName ?? "-",
                      bold: true,
                      background: doc.docCategoryId === 525 ? "#86f7aa" : "#FFFFFF",
                    },
                    { text: `\n Order Date:  ${new Date().toLocaleDateString()}` },
                    {
                      text: doc.createdAt
                        ? new Date(doc.createdAt).toLocaleDateString("en-US", {
                          year: "numeric",
                          month: "short",
                          day: "2-digit",
                        })
                        : "-",
                      bold: true,
                    },
                    { text: "\n\nAdditional Service Requested: " },
                    {
                      text: "\n PRE-SCAN: ",
                      background: doc.isScan ? "#FFFF00" : "#FFFFFF",
                    },
                    {
                      text: doc.isScan ? "Yes" : "No",
                      bold: true,
                      background: doc.isScan ? "#FFFF00" : "#FFFFFF",
                    },
                    {
                      text: "\n POST-SCAN: ",
                      background: doc.isPostScan ? "#FFFF00" : "#FFFFFF",
                    },
                    {
                      text: doc.isPostScan ? "Yes" : "No",
                      bold: true,
                      background: doc.isPostScan ? "#FFFF00" : "#FFFFFF",
                    },
                    {
                      text: "\n RUSH: ",
                      background: doc.isRush ? "#FD958D" : "#ffffff",
                    },
                    {
                      text: doc.isRush ? "Yes" : "No",
                      bold: true,
                      background: doc.isRush ? "#FD958D" : "#ffffff",
                    },
                    {
                      text:doc.isGeneralSoftCopy ==="651" ? "Process the document with attachment" :"Customer is sending original document",
                      bold: true,
                      // background:doc.isGeneralSoftCopy ==="651" ? "#FFFF00" : "#00FFFF",
                      Margin: [5, 0, 0, 0],
                      italics: true,
                    }    
                  ],
                },
                // Middle column - Customer details
                {
                  width: "33.33%",
                  text: [
                    "\n Customer Id: ",
                    { text: data.userDetails.customerId ?? "-", bold: true },
                    { text: "\n Customer Name: " },
                    { text: data.userDetails.customerName ?? "-", bold: true },
                    { text: "\n POC Name: " },
                    { text: data.userDetails.userName ?? "-", bold: true },
                    { text: "\n Email: " },
                    { text: data.userDetails.email ?? "-", bold: true },
                    { text: "\n Phone: " },
                    { text: data.userDetails.contactNo ?? "-", bold: true },
                    { text: "\n\n" },
                    { text: "\n PO/Invoice Ref: " },
                    {
                      text: doc.invoiceReference ?? "Not Provided",
                      bold: true,
                    },
                    { text: "\n Customer Ref: " },
                    {
                      text: doc.internalReference ? doc.internalReference : "Not Provided",
                      bold: true,
                    },
                    { text: "\n Payment: " },
                    {
                      text: data.shppingInstructions?.payLaterOptions
                        ? `Pay later (${data.shppingInstructions.payLaterOptions})`
                        : (doc.orderAmount ?? 0) <= (doc.paidAmount ?? 0)
                          ? "Paid"
                          : "Payment Due",
                      bold: true,
                    },
                  ],
                },
                // Right column - Billing and shipping
                {
                  width: "33.33%",
                  text: [
                    "\n Billing Address: ",
                    { text: "\n" + (data.returnAddress?.address ?? "-"), bold: true },
                    { text: "\n\nReturn/Shipping Instructions: " },
                    {
                      text:
                        data?.shppingInstructions?.regionId === -1
                          ? "\nE-Copy Only"
                          : data?.shppingInstructions?.regionId &&
                              data?.shppingInstructions?.regionId > 0
                          ? "\n*Use WCS Courier Account for additional fee"
                          : data.shppingInstructions?.useUserCourier
                            ? "\n*Use Prepaid Label Uploaded"
                            : data.shppingInstructions?.labelByMail
                              ? "\nEnclose Return Shipping Label by mail with documents"
                              : data.shppingInstructions?.pickupOrDropOff
                                ? "\nPickup / Dropoff"
                                : "",
                      bold: true,
                      italics: true,
                    },
                    {
                      text:
                        data.shppingInstructions?.regionId &&
                        data.shppingInstructions?.regionId > 0
                          ? "\n\nReturn Address: "
                          : "",
                      italics: true,
                    },
                    {
                      text: data.region
                        ? `\n${data.region.contactName}, ${data.region.address}\n${data.region.city}, ${data.region.country}, ${data.region.postalCode}\n${data.region.phoneNumber}`
                        : "",
                      italics: true,
                    },
                  ],
                },
              ],
              fontSize: 11,
            },
          ],
        ],
      },
      layout: {
        hLineWidth: (i: number, node: any) => 1,
        vLineWidth: (i: number, node: any) => 1,
        hLineColor: (i: number, node: any) =>
          i === 0 || i === node.table.body.length ? "#cccccc" : "white",
        vLineColor: (i: number, node: any) =>
          i === 0 || i === node.table.widths.length ? "#cccccc" : "white",
      },
    });

    // Customer Comments section
    content.push({
      table: {
        widths: ["*"],
        body: [
          [
            {
              text: "\n\n Customer Comments:\n",
              bold: true,
              fontSize: 11,
              margin: [0, -19],
            },
          ],
          [
            {
              text:
                doc.instructions && doc.instructions.trim().length > 0
                  ? doc.instructions
                  : "No Information Provided",
              fontSize: 11,
              margin: [0, 20],
            },
          ],
        ],
      },
      layout: {
        hLineWidth: () => 1,
        vLineWidth: () => 1,
        hLineColor: (i: number, node: any) =>
          i === 0 || i === node.table.body.length ? "#cccccc" : "white",
        vLineColor: (i: number, node: any) =>
          i === 0 || i === node.table.widths.length ? "#cccccc" : "white",
      },
    });

    // Processing Stops & Timelines section
    if (doc.stops && doc.stops.length > 0) {
      const stopData: any[] = [];

      doc.stops.forEach((stop) => {
        stopData.push({
          text: [
            {
              fontSize: 9,
              bold: true,
              text: `${stop.description || stop.stopName}\n`,
            },
            {
              fontSize: 9,
              text: `${stop.processDays ?? "-"} business days`,
            },
          ],
        });
      });

      if (stopData.length > 0 && doc.estDateOfCompletion) {
        stopData.push({
          text: [
            { fontSize: 9, bold: true, text: "Estimated Completion\n" },
            {
              fontSize: 9,
              bold: true,
              text: new Date(doc.estDateOfCompletion).toLocaleDateString("en-US", {
                year: "numeric",
                month: "long",
                day: "numeric",
              }),
            },
          ],
        });
      }

      content.push({
        table: {
          widths: ["*"],
          body: [
            [
              {
                text: "\nProcessing Stops & Timelines:\n\n",
                bold: true,
                fontSize: 11,
              },
            ],
            [
              {
                table: {
                  body: [stopData],
                },
                layout: {
                  hLineColor: () => "#cccccc",
                  vLineColor: () => "#cccccc",
                  paddingLeft: () => 10,
                  paddingRight: () => 10,
                  paddingTop: () => 10,
                  paddingBottom: () => 10,
                },
              },
            ],
          ],
        },
        layout: {
          hLineWidth: () => 1,
          vLineWidth: () => 1,
          hLineColor: (i: number, node: any) =>
            i === 0 || i === node.table.body.length ? "#cccccc" : "white",
          vLineColor: (i: number, node: any) =>
            i === 0 || i === node.table.widths.length ? "#cccccc" : "white",
        },
      });
    }

    // Customer Instructions section (if any)
    const embassyContent = getEmbassySidebarContent(doc.countryName);
    const taiwanExtraInstructions = [
      "Please take a print of this order form and send it along with the documents.",
      "Originals are required for legalization of General document for Taiwan. Processing will be initiated after WCS receives the originals.",
    ];
    const customerInstructions: string[] = [];

    if (doc.instructionsList?.length) {
      customerInstructions.push(...doc.instructionsList);
    }

    if ((doc.countryName ?? "").trim().toLowerCase() === "taiwan") {
      customerInstructions.push(...taiwanExtraInstructions);
    }
    if (embassyContent) {
      customerInstructions.push(...embassyContent.paragraphs);
    }

    const normalizedCustomerInstructions = Array.from(
      new Set(
        customerInstructions
          .map((instruction) => instruction.trim())
          .filter((instruction) => instruction.length > 0)
      )
    );

    if (normalizedCustomerInstructions.length > 0) {
      content.push({
        table: {
          widths: ["*"],
          body: [
            [
              {
                text: "\nCustomer Instructions:\n",
                bold: true,
                fontSize: 11,
              },
            ],
            [
              {
                ul: normalizedCustomerInstructions,
                fontSize: 10,
                margin: [0, 0, 0, 6],
              },
            ],
          ],
        },
        layout: {
          hLineWidth: () => 1,
          vLineWidth: () => 1,
          hLineColor: (i: number, node: any) =>
            i === 0 || i === node.table.body.length ? "#cccccc" : "white",
          vLineColor: (i: number, node: any) =>
            i === 0 || i === node.table.widths.length ? "#cccccc" : "white",
        },
      });
    }

    // Page break after each document except last
    if (index < data.documents.length - 1) {
      content.push({
        text: " ",
        pageBreak: "after",
      });
    }
  });

  // ---------- PDF Configuration ----------
  const pdfConfig: any = {
    images: {
      logo: logoBase64,
    },
    pageMargins: [9, 9, 9, 9],
    pageOrientation: "portrait",
    content,
    footer: (currentPage: number, pageCount: number) => ({
      text: `Pages ${currentPage} of ${pageCount}`,
      alignment: "center",
      margin: [0, 30, 0, 0],
    }),
    defaultStyle: {
      fontSize: 10,
    },
  };

  const pdfDoc = (pdfMake as any).createPdf(pdfConfig)

  switch (action) {
    case "open":
      pdfDoc.open();
      break;

    case "print":
      pdfDoc.print();
      break;

    default:
      pdfDoc.download(data.fileName);
  }
};
